
create table if not exists public.creator_partnerships (
  id bigint primary key,
  rank integer not null,
  fit_score integer not null,
  priority text not null,
  creator_name text not null,
  instagram_handle text not null default '',
  description text not null default '',
  followers bigint not null default 0,
  engagement_rate numeric not null default 0,
  fit_rationale text not null default '',
  status text not null default 'new' check (status in ('new','contacted','accepted','rejected','disqualified')),
  owner_id uuid not null references auth.users(id) on delete cascade,
  updated_at timestamptz not null default now()
);
create table if not exists public.collaboration_dm_templates (
  id bigint generated by default as identity primary key,
  name text not null,
  body text not null,
  owner_id uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
alter table public.creator_partnerships enable row level security;
alter table public.collaboration_dm_templates enable row level security;
drop policy if exists "Owners manage creator partnerships" on public.creator_partnerships;
create policy "Owners manage creator partnerships" on public.creator_partnerships for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
drop policy if exists "Owners manage collaboration templates" on public.collaboration_dm_templates;
create policy "Owners manage collaboration templates" on public.collaboration_dm_templates for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select, insert, update, delete on public.creator_partnerships to authenticated;
grant select, insert, update, delete on public.collaboration_dm_templates to authenticated;
grant usage, select on sequence public.collaboration_dm_templates_id_seq to authenticated;
do $$
declare target_user uuid;
begin
  select id into target_user from auth.users order by created_at asc limit 1;
  if target_user is null then raise exception 'No authenticated user exists for collaboration ownership'; end if;
  on conflict (id) do update set rank=excluded.rank, fit_score=excluded.fit_score, priority=excluded.priority, creator_name=excluded.creator_name, instagram_handle=excluded.instagram_handle, description=excluded.description, followers=excluded.followers, engagement_rate=excluded.engagement_rate, fit_rationale=excluded.fit_rationale, updated_at=now();
  if not exists (select 1 from public.collaboration_dm_templates where owner_id = target_user) then
  end if;
end $$;
