    insert into public.collaboration_dm_templates (name, body, owner_id) values
      ('Warm Introduction', 'Hey {{name}} — love your content. I wrote Get Sh*t Done, a funny, practical book for brains that refuse to behave in 2026. Your audience feels like a great fit. We pay $3 for every book sold through your affiliate link, and we’re starting with the book but have workbooks, follow-on books, and merch coming. Check it out at gsd-book.com or @hankandthesquirrel. Interested?', target_user),
      ('Commission-First', 'Hey {{name}} — we’re offering creators $3 per Get Sh*t Done book sold through their affiliate link. I love what you’re doing at {{handle}}, and the overlap with our ADHD-friendly, anti-fluff approach feels real. This starts with the book, with workbooks, more books, and merch coming. Take a look at gsd-book.com and let me know if you want in.', target_user),
      ('Quick Follow-Up', 'Hey {{name}} — quick squirrel-brain follow-up in case my last note got buried. I’d still love to explore a GSD affiliate partnership. $3 per book sold, simple tracking, no corporate interpretive dance. Want the details?', target_user);
